} else if( !inside.giesecke &  add.sites | sitename %in% c("Lake Prespa", "Lake Ohrid", "Lake Van") ){ 

    # use the pollen counts (summed up over the AP) as the reference (like in many papers)
    quali.reconstr.ref.depth <- core.data[[station_id]]$qualitativ_data$qualitativ_reconstruction


    if(length(quali.reconstr.ref.depth) == 0){ 
        quali.reconstr.ref.depth <- rowSums(core.data[[station_id]]$all.available.taxa$taxa.spectrum,na.rm=T)
    }


    # age-depth trafo
    predictors$pollen <- quali.reconstr.ref.age <- (rho.d.g.a %*% as.matrix(quali.reconstr.ref.depth))[,1]
    if(anyNA(predictors$pollen)){
        which_na <- which(is.na(predictors$pollen))
        predictors$pollen[which_na] <- predictors$pollen[which_na[1]-1]
    }
    common.age.pollen <- c(1:length(predictors$pollen)) 
    pollen.age <- site.age

    if(sitename == "Lake Iznik") predictors$pollen <- predictors$pollen/max(predictors$pollen)*90

    #-----------------------------------------------------------------------------------------------

    # note in sources
    sources$core <- 1
    if( var(predictors$pollen[pollen.age %in% site.age], na.rm=T)== 0 ) sources$core <- 0

#     df_speleo <- data.frame(age = iso.ref.norm$age, iso = z)

    # wavelet parameter
    s0 <- 2*diff(site.age)[1]
    if(s0 == 100) s0 <- 400
    max.scale <- floor(diff(range(site.age))/2)


    df_speleo <- smoothing(iso.ref)
    df_speleo$isotopes[1:8] <- iso.ref$isotopes[1:8]

    # IRD in spectral space
    if( any(sitename == c("","")) ){
        df_speleo <- data.frame(age = ird_data$age, isotopes = ird_data$isotopes)
        cave_name <- "IRD"
    }

    # human impact
    human_impact <- core.data[[station_id]]$human_impact
    hi_spec <- FALSE
    if(case_studies) human_impact <- NULL
    if(length(human_impact) != 0 & !any(sitename == c("Lake Kinneret","En Gedi","Birkat Ram")) ){
        hi_spec <- TRUE
        hi_ages_spec <- !inside.range(site.age[common.age.spec],human_impact)
    }else{
        hi_ages_spec <- rep(TRUE,length(which(common.age.spec == TRUE)))
    }


    df_speleo_nhp <- df_speleo[hi_ages_spec,]
    df_speleo_hp <- df_speleo[!hi_ages_spec,]
#     wt.speleo <- wt(iso.spec, s0 = s0, dj = 1/12, max.scale = max.scale, do.sig = FALSE)


    if(diff(range(site.age[common.age.spec])) <= 12000){
        dj <- 1/12
    }else{
        dj <- 1/8
    }

    # coin of influence
    period <-  wt(df_speleo_nhp, s0 = s0, dj = dj, max.scale = max.scale, do.sig = FALSE)$period 
    coi <- wt(df_speleo_nhp, s0 = s0, dj = dj, max.scale = max.scale, do.sig = FALSE)$coi
    coi_array <- array(1, dim = dim(wt(df_speleo_nhp, s0 = s0, dj = dj, max.scale = max.scale, do.sig = FALSE)$power))

    for(i in 1:length(period)){
        for(j in 1:length(coi)){ 
            if( coi[j] < period[i]  ) coi_array[i,j] <- 0

#-------------------------------------------------------------------------------------------------------------------------



