            posterior_temp$post_iso_hi <- posterior_temp$post_iso_hi^2
        }else{
            posterior_temp$post_iso_hi <- 0.95
        }

    }

    # spectral space: only if spleoethem data are available (pattern correlation)
    if(spectral){
