        predictant_spec <- c(wt_power(predictant_current[ages_spec][hi_ages_spec],length_ages_spec2, n.obs=n.obs, zeros=zeros, invflen=invflen)[coi_array == 1])
        posterior_temp$post_spec <- cor(predictant_spec,predictors$iso_spec,na.rm=TRUE)
